async function attach_photo(params, userSettings, resources) {
  // The ONLY reason this function is JavaScript rather than an HTTP Action
  // like every other tool in this plugin: TypingMind hands a message's
  // attachments to JavaScript functions and to nothing else. An HTTP Action
  // cannot see an attached photograph at all.
  const MAX_EDGE = 1600;

  const images = (resources?.userMessage?.attachments || []).filter((a) =>
    a.type?.startsWith('image/'),
  );

  if (!images.length) {
    return {
      ok: false,
      message:
        'No photograph is attached to that message. Ask the user to attach the ' +
        'picture to the message naming the recipe, then call this again.',
    };
  }

  // If several came at once, the last one is the one just taken.
  const chosen = images[images.length - 1];

  const asDataURL = (blob) =>
    new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });

  // Shrink before sending. A phone photograph is several megabytes, the
  // service resizes it again anyway, and re-encoding through a canvas is also
  // what gets an iPhone HEIC through - the browser decodes it and hands back
  // a JPEG. If any of that fails, the original bytes go instead and the
  // service has its own go.
  const shrink = async (blob) => {
    try {
      const bitmap = await createImageBitmap(blob);
      const scale = Math.min(1, MAX_EDGE / Math.max(bitmap.width, bitmap.height));
      const width = Math.round(bitmap.width * scale);
      const height = Math.round(bitmap.height * scale);

      if (typeof OffscreenCanvas !== 'undefined') {
        const canvas = new OffscreenCanvas(width, height);
        canvas.getContext('2d').drawImage(bitmap, 0, 0, width, height);
        const out = await canvas.convertToBlob({
          type: 'image/jpeg',
          quality: 0.85,
        });
        return await asDataURL(out);
      }

      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      canvas.getContext('2d').drawImage(bitmap, 0, 0, width, height);
      return canvas.toDataURL('image/jpeg', 0.85);
    } catch (e) {
      return null;
    }
  };

  let encoded;
  try {
    const blob = await fetch(chosen.url).then((r) => r.blob());
    encoded = (await shrink(blob)) || (await asDataURL(blob));
  } catch (e) {
    return {
      ok: false,
      message:
        'The attached photograph could not be read in the browser, so nothing ' +
        'was changed: ' + e.message,
    };
  }

  const response = await fetch(
    userSettings.serviceUrl.replace(/\/+$/, '') + '/v1/recipes/photo',
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: 'Bearer ' + userSettings.serviceToken,
      },
      body: JSON.stringify({ uid: params.uid, image_base64: encoded }),
    },
  );

  if (!response.ok) {
    return {
      ok: false,
      message:
        'The service refused the photograph (HTTP ' + response.status + '): ' +
        (await response.text()),
    };
  }

  return await response.json();
}

async function add_equipment(params, userSettings, resources) {
  // Reading the attached photo, exactly as attach_photo does it. This has to
  // be a JavaScript function because TypingMind hands a message's attachments
  // to JavaScript functions and to nothing else.
  const MAX_EDGE = 1600;

  const asDataURL = (blob) =>
    new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });

  // Shrink in the browser: a phone photo is several megabytes, and drawing it
  // through a canvas is also what turns an iPhone HEIC into a JPEG.
  const shrink = async (blob) => {
    try {
      const bitmap = await createImageBitmap(blob);
      const scale = Math.min(1, MAX_EDGE / Math.max(bitmap.width, bitmap.height));
      const width = Math.round(bitmap.width * scale);
      const height = Math.round(bitmap.height * scale);
      if (typeof OffscreenCanvas !== 'undefined') {
        const canvas = new OffscreenCanvas(width, height);
        canvas.getContext('2d').drawImage(bitmap, 0, 0, width, height);
        return await asDataURL(await canvas.convertToBlob({ type: 'image/jpeg', quality: 0.85 }));
      }
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      canvas.getContext('2d').drawImage(bitmap, 0, 0, width, height);
      return canvas.toDataURL('image/jpeg', 0.85);
    } catch (e) {
      return null;
    }
  };

  // Returns the encoded photo, "" when none is attached, or throws.
  const attachedPhoto = async () => {
    const images = (resources?.userMessage?.attachments || []).filter((a) =>
      a.type?.startsWith('image/'),
    );
    if (!images.length) return '';
    const chosen = images[images.length - 1];
    const blob = await fetch(chosen.url).then((r) => r.blob());
    return (await shrink(blob)) || (await asDataURL(blob));
  };

  const send = async (path, body) => {
    let response;
    try {
      response = await fetch(userSettings.serviceUrl.replace(/\/+$/, '') + path, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: 'Bearer ' + userSettings.serviceToken,
        },
        body: JSON.stringify(body),
      });
    } catch (e) {
      return { ok: false, message: 'The service could not be reached, so nothing was changed: ' + e.message };
    }
    if (!response.ok) {
      return {
        ok: false,
        message: 'The service refused it (HTTP ' + response.status + '), so nothing was changed: ' + (await response.text()),
      };
    }
    return await response.json();
  };
  const { use_attached_photo, ...item } = params;
  let image_base64 = '';
  let photoNote = '';
  if (use_attached_photo !== false) {
    try {
      image_base64 = await attachedPhoto();
    } catch (e) {
      photoNote = ' The attached photo could not be read in the browser (' + e.message + '), so it was added without one.';
    }
  }

  const result = await send('/v1/equipment/add', { ...item, image_base64 });
  if (photoNote && result.message) result.message += photoNote;
  return result;
}

